113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        normalizeAddress(ownerFieldsDto);
116	        validateRequiredFields(ownerFieldsDto);
117	        normalizeTelephone(ownerFieldsDto);
118	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
119	        rejectDuplicateHousehold(ownerFieldsDto);
120	        rejectCityAtCapacity(ownerFieldsDto.getCity());
121	        normalizeEmail(ownerFieldsDto);
122	        defaultRegistrationDate(ownerFieldsDto);
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        assignCustomerCode(owner);
126	        assignHouseholdId(owner);
127	        assignNamesakeCount(owner);
128	        assignMembershipNumber(owner);
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
