195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	            }
198	        }
199	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
213	            .buildAndExpand(visit.getId()).toUri());
214	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
215	    }
216	
217	
218	    /**
219	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
220	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
221	     * Validation already rejects {@code null} values and the pattern-constrained fields
222	     * when blank, but {@code address} and {@code city} have no pattern, so a
223	     * whitespace-only value would otherwise slip through.
224	     *
225	     * @param ownerFieldsDto the submitted owner fields
226	     * @throws RequiredFieldsMissingException if any required field is missing or blank
227	     */
228	    /**
229	     * Common street-type abbreviations expanded during address normalization. Keys are the
230	     * upper-cased abbreviation tokens; values are their canonical expansions.
231	     */
232	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
233	        "ST", "STREET",
234	        "RD", "ROAD",
235	        "AVE", "AVENUE");
236	
237	    /**
238	     * Normalizes the submitted address on create and writes the canonical value back onto the
239	     * request so it is persisted, echoed back, and used for every downstream address comparison
240	     * (household duplicate detection and the household id). The value is trimmed, internal
241	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
242	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
243	     * {@code null} address is left untouched so the required-field check can report it as missing.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields
246	     */
247	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
248	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
249	    }
250	
251	    /**
252	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
253	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
254	     * expanded to its full form. A {@code null} value is returned unchanged.
255	     *
256	     * @param raw the address to canonicalize, possibly {@code null}
257	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
258	     */
259	    private static String normalizeAddress(String raw) {
260	        if (raw == null) {
261	            return null;
262	        }
263	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
264	        if (collapsed.isEmpty()) {
265	            return collapsed;
266	        }
267	        String[] tokens = collapsed.split(" ");
268	        StringBuilder sb = new StringBuilder(collapsed.length());
269	        for (int i = 0; i < tokens.length; i++) {
270	            if (i > 0) {
271	                sb.append(' ');
272	            }
273	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
274	        }
275	        return sb.toString();
276	    }
277	
278	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
279	        List<String> errors = new ArrayList<>();
280	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
281	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
282	        requireText("address", ownerFieldsDto.getAddress(), errors);
283	        requireText("city", ownerFieldsDto.getCity(), errors);
284	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
285	        if (!errors.isEmpty()) {
286	            throw new RequiredFieldsMissingException(errors);
287	        }
288	    }
289	
290	    private static void requireText(String field, String value, List<String> errors) {
291	        if (value == null || value.isBlank()) {
292	            errors.add(field);
293	        }
294	    }
295	
296	    /**
297	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
298	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
299	     * and echoed back in that form.
300	     *
301	     * @param ownerFieldsDto the submitted owner fields
302	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
303	     *                                        valid E.164 number
304	     */
305	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
306	        String e164 = toE164(ownerFieldsDto.getTelephone());
307	        if (e164 == null) {
308	            throw new RequiredFieldsMissingException(List.of("telephone"));
309	        }
310	        ownerFieldsDto.setTelephone(e164);
311	    }
312	
313	    /**
314	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
315	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
316	     * and country code are present they are kept; otherwise country code {@code '+61'} is
317	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
318	     * must contain 8 to 15 digits after the {@code '+'}.
319	     *
320	     * @param raw the submitted telephone, possibly {@code null}
321	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
322	     */
323	    private static String toE164(String raw) {
324	        if (raw == null) {
325	            return null;
326	        }
327	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
328	        String digits;
329	        if (cleaned.startsWith("+")) {
330	            digits = cleaned.substring(1);
331	        } else {
332	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
333	            digits = "61" + national;
334	        }
335	        if (!digits.matches("[0-9]{8,15}")) {
336	            return null;
337	        }
338	        return "+" + digits;
339	    }
340	
341	    /**
342	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
343	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
344	     * each stored owner's telephone is normalized the same way before comparison so differing
345	     * input formats collapse to the same value.
346	     *
347	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
348	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
349	     *                                     same E.164 telephone
350	     */
351	    /**
352	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
353	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
354	     * the parts may contain whitespace or a second {@code @}.
355	     */
356	    private static final Pattern EMAIL_PATTERN =
357	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
358	
359	    /**
360	     * Normalizes the submitted email when present: the value is trimmed, required to be a
361	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
362	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
363	     *
364	     * @param ownerFieldsDto the submitted owner fields
365	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
366	     */
367	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
368	        String email = ownerFieldsDto.getEmail();
369	        if (email == null) {
370	            return;
371	        }
372	        String trimmed = email.strip();
373	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
374	            throw new InvalidEmailException(email);
375	        }
376	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
377	    }
378	
379	    /**
380	     * Defaults the registration date on create: when the client does not supply a
381	     * {@code registrationDate}, it is set to the server's current date so it is persisted
382	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
383	     *
384	     * @param ownerFieldsDto the submitted owner fields
385	     */
386	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
387	        if (ownerFieldsDto.getRegistrationDate() == null) {
388	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
389	        }
390	    }
391	
392	    /**
393	     * Assigns the owner's {@code customerCode} on create, formatted
394	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
395	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
396	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
397	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
398	     *
399	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
400	     */
401	    private void assignCustomerCode(Owner owner) {
402	        String city = owner.getCity();
403	        String lastName = owner.getLastName();
404	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
405	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
406	        long sequence = this.clinicService.findAllOwners().stream()
407	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
408	            .count() + 1;
409	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
410	    }
411	
412	    /**
413	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
414	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
415	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
416	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
417	     * canonicalized fields, every owner in the same household — including one joining an existing
418	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
419	     * order.
420	     *
421	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
422	     */
423	    private void assignHouseholdId(Owner owner) {
424	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
425	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
426	    }
427	
428	    /**
429	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
430	     * already share this owner's {@code firstName} and {@code lastName}, compared
431	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
432	     * pre-existing namesakes.
433	     *
434	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
435	     */
436	    private void assignNamesakeCount(Owner owner) {
437	        String firstName = owner.getFirstName();
438	        String lastName = owner.getLastName();
439	        long count = this.clinicService.findAllOwners().stream()
440	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
441	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
442	            .count();
443	        owner.setNamesakeCount((int) count);
444	    }
445	
446	    /**
447	     * Assigns the owner's {@code membershipNumber} on create, formatted
448	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
449	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
450	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
451	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
452	     *
453	     * @param owner the owner being created (with its {@code customerCode} and
454	     *              {@code registrationDate} already set)
455	     */
456	    private void assignMembershipNumber(Owner owner) {
457	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
458	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
459	    }
460	
461	    /**
462	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
463	     *
464	     * @param value the string to hash
465	     * @return the 64-character lower-case hex digest
466	     */
467	    private static String sha256Hex(String value) {
468	        try {
469	            byte[] digest = MessageDigest.getInstance("SHA-256")
470	                .digest(value.getBytes(StandardCharsets.UTF_8));
471	            StringBuilder sb = new StringBuilder(digest.length * 2);
472	            for (byte b : digest) {
473	                sb.append(String.format("%02x", b));
474	            }
475	            return sb.toString();
476	        }
477	        catch (NoSuchAlgorithmException e) {
478	            throw new IllegalStateException("SHA-256 not available", e);
479	        }
480	    }
481	
482	    private void rejectDuplicateTelephone(String normalizedTelephone) {
483	        boolean duplicate = this.clinicService.findAllOwners().stream()
484	            .map(Owner::getTelephone)
485	            .map(OwnerRestControllerV1::toE164)
486	            .filter(telephone -> telephone != null)
487	            .anyMatch(normalizedTelephone::equals);
488	        if (duplicate) {
489	            throw new DuplicateTelephoneException(normalizedTelephone);
490	        }
491	    }
492	
493	    /**
494	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
495	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
496	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
497	     * still counts as the same household. The check is skipped when the request opts in via
498	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
499	     * the existing one.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields
502	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
503	     *                                     last name and address and the request did not opt in
504	     */
505	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
506	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
507	            return;
508	        }
509	        String lastName = collapse(ownerFieldsDto.getLastName());
510	        String address = collapse(ownerFieldsDto.getAddress());
511	        boolean duplicate = this.clinicService.findAllOwners().stream()
512	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
513	                && collapse(owner.getAddress()).equals(address));
514	        if (duplicate) {
515	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
516	        }
517	    }
518	
519	    /**
520	     * The maximum number of owners permitted in a single city. A create is rejected once the
521	     * owner's city already contains this many owners.
522	     */
523	    private static final long CITY_CAPACITY = 50;
524	
525	    /**
526	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
527	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
528	     * before this owner is persisted.
529	     *
530	     * @param city the submitted city
531	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
532	     */
533	    private void rejectCityAtCapacity(String city) {
534	        long count = this.clinicService.findAllOwners().stream()
535	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
536	            .count();
537	        if (count >= CITY_CAPACITY) {
538	            throw new CityAtCapacityException(city);
539	        }
540	    }
541	
542	    /**
543	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
544	     * every internal run of whitespace is collapsed to a single space, and the result is
545	     * lower-cased. A {@code null} value collapses to the empty string.
546	     *
547	     * @param value the value to canonicalize, possibly {@code null}
548	     * @return the collapsed, lower-cased value
549	     */
550	    private static String collapse(String value) {
551	        if (value == null) {
552	            return "";
553	        }
554	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
555	    }
556	
557	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
558	    @Override
559	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
560	        Owner owner = this.clinicService.findOwnerById(ownerId);
561	        if (owner != null) {
562	            Pet pet = owner.getPet(petId);
563	            if (pet != null) {
564	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
565	            }
566	        }
567	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
568	    }
569	}
